// Review the production component renderings generated by the content check.
import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {chromium} from 'playwright';
const out='work/chemistry-2025-preview';
const questions=['s1','s2','s3','r1','r2','r3'].flatMap(t=>JSON.parse(readFileSync(`content/ib/chemistry-2025-practice/${t}.json`,'utf8')));
const browser=await chromium.launch({headless:true,...(process.env.CHROME_BIN?{executablePath:process.env.CHROME_BIN}:{})});
const report={status:'passed',desktopViews:0,mobileViews:0,screenshots:[],checks:['all question and scheme pages display at desktop width','all question pages display at 390px width','no document horizontal overflow','all figure images decode','no KaTeX error elements'],scope:'Local production component renderings with test authentication; no live student account used.'};
const jobs=questions.flatMap(q=>[{q,scheme:false,width:1440},{q,scheme:true,width:1440},{q,scheme:false,width:390}]);
const samples=new Set(['ib-chem-s1-803','ib-chem-r3-817','ib-chem-s3-825']);
try{
 await Promise.all(Array.from({length:4},async()=>{
  const page=await browser.newPage();
  while(jobs.length){
   const {q,scheme,width}=jobs.shift(),name=q.id+(scheme?'-scheme':'');
   await page.setViewportSize({width,height:1000});
   await page.goto(pathToFileURL(resolve(out,`${name}.html`)).href);
   await page.evaluate(()=>document.fonts.ready);
   const state=await page.evaluate(()=>({overflow:document.documentElement.scrollWidth>innerWidth+1,mathErrors:document.querySelectorAll('.katex-error').length,broken:[...document.images].filter(i=>!i.complete||i.naturalWidth===0).length,text:document.body.innerText.length}));
   assert.equal(state.mathErrors,0,name);assert.equal(state.broken,0,name);assert.equal(state.overflow,false,name+' at '+width+'px');assert.ok(state.text>100,name);
   report[width===390?'mobileViews':'desktopViews']++;
   if(!scheme&&samples.has(q.id)){const file=`${out}/${q.id}-${width}.png`;await page.screenshot({path:file,fullPage:true});report.screenshots.push(file);}
  }
  await page.close();
 }));
 assert.equal(report.desktopViews,400);assert.equal(report.mobileViews,200);
 writeFileSync('docs/ib-chemistry-2025-practice/browser-review.json',JSON.stringify(report,null,2)+'\n');
 console.log(JSON.stringify(report));
}finally{await browser.close();}
